// Custom Worker entry: the OpenNext app for HTTP plus a daily cron for transactional emails.
// https://opennext.js.org/cloudflare/howtos/custom-worker
import type { D1Database, ExecutionContext, ExportedHandler, ScheduledController } from "@cloudflare/workers-types";
// @ts-ignore — generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";

type Env = { EGG_DB: D1Database; APP_URL?: string };

async function cronSecret(env: Env): Promise<string> {
  const row = await env.EGG_DB.prepare("SELECT value FROM app_settings WHERE key = 'cron_secret'").first<{ value: string }>();
  if (row?.value) return row.value;
  const bytes = crypto.getRandomValues(new Uint8Array(32));
  const value = Array.from(bytes, (b) => b.toString(16).padStart(2, "0")).join("");
  await env.EGG_DB
    .prepare("INSERT INTO app_settings (key, value, updated_at, updated_by) VALUES ('cron_secret', ?, ?, 'cron') ON CONFLICT(key) DO NOTHING")
    .bind(value, Date.now())
    .run();
  const again = await env.EGG_DB.prepare("SELECT value FROM app_settings WHERE key = 'cron_secret'").first<{ value: string }>();
  return again!.value;
}

export default {
  fetch: handler.fetch,

  async scheduled(_event: ScheduledController, env: Env, ctx: ExecutionContext) {
    const base = (env.APP_URL ?? "https://easygoldglitch.com").replace(/\/$/, "");
    const secret = await cronSecret(env);
    // Run the Next route in-process (no network hop) so it shares the app's mail code.
    const res: Response = await handler.fetch(
      new Request(`${base}/api/cron/reminders`, { method: "POST", headers: { "x-gg-cron": secret } }),
      env,
      ctx,
    );
    console.log("cron reminders", res.status, await res.text());
  },
} satisfies ExportedHandler<Env>;

// @ts-ignore — Durable Objects used by OpenNext's caches
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";
